// src/lib/plattform/backend/index.js
//
// Einheitliche Backend-Schnittstelle der Plattform. Zwei Implementierungen:
//   frappe.js – Frappe-App `oekoinvest_app` (Produktion), Auswahl mit PLATTFORM_BACKEND=frappe
//   demo.js   – JSON-Datei unter .data/plattform.json (Entwicklung/Vorführung)
//
// Im Produktions-Build wird das Demo-Backend NUR genutzt, wenn PLATTFORM_DEMO=1 gesetzt ist –
// sonst gibt es eine klare Fehlermeldung (HTTP 503) statt stiller Demo-Daten.
//
// Nur serverseitig verwenden (Route-Handler, Server-Komponenten).
//
// Alle Operationen (Signaturen identisch in beiden Implementierungen; n = angemeldeter Nutzer):
//   Konto:     anmelden({email,passwort}) · nutzerFuerSitzung(id) · registrieren({...}) · emailBestaetigen({token})
//              passwortVergessen({email,basisUrl,ip}) · passwortSetzen({token,passwort,ip}) · passwortAendern(n,{alt,neu})
//              profilSpeichern(n,daten) · suchprofilSpeichern(n,profil)
//   Anfrage:   anfrageAnlegen({typ,kontakt,daten,herkunft,ip,einwilligungText,nutzer})
//   Vorgänge:  vorgaenge(n,{alle,status,typ,q}) · vorgang(n,id)
//   Flächen:   flaechen(n,{alle,status}) · flaeche(n,id) · flaecheAnlegen(n,daten,{ip}) · flaecheAendern(n,id,daten)
//   Projekte:  projekte(n,{alle,status}) · projekt(n,id) · projektAnlegen(n,daten,{ip}) · projektAendern(n,id,daten)
//              provisionAkzeptieren(n,id,{ip})
//   Börse:     boerse(n|null,filter) · boerseDetail(n|null,slugOderId,{zaehlen})
//   Interesse: merken(n,projektId,an) · ndaAnfragen(n,projektId,{akzeptiert,ip,userAgent}) · interessen(n,{alle,status,projektId})
//   Prozess:   statusWechsel(n,{art,id,nach,als,extra,ip})
//   Nachricht: nachrichtenThreads(n) · nachrichten(n,bezugArt,bezugId,{markieren}) · nachrichtSenden(n,{bezugArt,bezugId,text})
//   Dokument:  dokumente(n,{bezugArt,bezugId}) · dokumentLesen(n,id) · dokumentSpeichern(n,{...,daten}) · dokumentLoeschen(n,id)
//   Admin:     zuweisen · nutzerListe · nutzerAendern · provisionen · aktivitaeten · adminKonten · adminUebersicht · demoLinks
//   Hinweise:  benachrichtigungen(n,{nurUngelesen,limit}) · benachrichtigungenGelesen(n,{ids,alle}) · mailEinstellungenSpeichern(n,einstellungen)
//   Aufgaben:  aufgaben(n,{zustaendigId,status,bezugArt,bezugId,nurUeberfaellig}) · aufgabeAnlegen(n,daten) · aufgabeAendern(n,id,daten)
//   Exposé:    exposeDaten(n,id,{ip}) (Rechte + Protokoll, PDF erzeugt die Website) · protokollEintrag(n,{aktion,objektArt,objektId,text,ip})
//   Nur Demo:  postausgang(n,{limit}) (E-Mails, die Frappe versenden würde; im Frappe-Adapter [])

import * as demo from "./demo";
import * as frappe from "./frappe";
import { PlattformFehler } from "../fehler";
import { BACKOFFICE_OPERATIONEN } from "./frappe/backoffice";

export const OPERATIONEN = [
  "anmelden", "nutzerFuerSitzung", "registrieren", "emailBestaetigen", "passwortVergessen", "passwortSetzen", "passwortAendern",
  "profilSpeichern", "suchprofilSpeichern", "anfrageAnlegen", "vorgaenge", "vorgang", "flaechen", "flaeche", "flaecheAnlegen",
  "flaecheAendern", "projekte", "projekt", "projektAnlegen", "projektAendern", "provisionAkzeptieren", "boerse", "boerseDetail",
  "merken", "ndaAnfragen", "interessen", "statusWechsel", "nachrichtenThreads", "nachrichten", "nachrichtSenden", "dokumente",
  "dokumentLesen", "dokumentSpeichern", "dokumentLoeschen", "zuweisen", "nutzerListe", "nutzerAendern", "provisionen",
  "aktivitaeten", "adminKonten", "adminUebersicht", "demoLinks", "benachrichtigungen", "benachrichtigungenGelesen",
  "mailEinstellungenSpeichern", "postausgang", "aufgaben", "aufgabeAnlegen", "aufgabeAendern", "exposeDaten", "protokollEintrag",
  ...BACKOFFICE_OPERATIONEN, // Backoffice: CRM, Akquise, Automationen, Vorlagen, Berichte, Rechte (backend/frappe/backoffice.js)
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Backend ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export const KONFIG_FEHLER =
  "Das Plattform-Backend ist nicht konfiguriert. Für den Betrieb PLATTFORM_BACKEND=frappe setzen (siehe docs/PLATTFORM.md) – oder PLATTFORM_DEMO=1 für eine reine Vorführung.";

export function backendName() {
  if (process.env.PLATTFORM_BACKEND === "frappe") return "frappe";
  if (process.env.NODE_ENV === "production" && process.env.PLATTFORM_DEMO !== "1") return null;
  return "demo";
}

/** Liefert die aktive Implementierung oder wirft 503 */
export function backend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

export const istDemo = () => backendName() === "demo";
// src/lib/plattform/backend/entwicklung.js
//
// Backend-Teil „Projektentwicklung“ (internes Entwicklungsmanagement; eigene Schnittstelle, backend/index.js bleibt
// unverändert). Gleiche Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build
// ohne PLATTFORM_DEMO=1). Vertrag: docs/API.md Abschnitt 11.
//
// Operationen (n = angemeldeter Nutzer):
//   Backoffice: entwicklungPortfolio(n,{q,status}) · entwicklungProjekt(n,id) · entwicklungAuswahl(n) · entwicklungAnlegen(n,daten)
//               entwicklungAendern(n,id,daten) · entwicklungEintragSpeichern(n,projektId,{art,id?,daten})
//               entwicklungEintragLoeschen(n,projektId,{art,id})  (art: flaeche|meilenstein|risiko|entscheidung|budget|kontakt|freigabe)
//               entwicklungAktion(n,projektId,{aktion,begruendung}) (plan_neu|vorlage_anwenden|uebergabe_boerse|uebergabe_anlage|erpnext_sync)
//               entwicklungAssistent(n,{flaecheId,land,typ,start}) · entwicklungGutachterEinladen(n,projektId,{email,meilensteinIds,basisUrl})
//               entwicklungFristen(n) (Erinnerungen; Frappe: Scheduler täglich)
//   Extern:     entwicklungMeine(n) · entwicklungExtern(n,id) · entwicklungMeilensteinMelden(n,projektId,meilensteinId,{aktion})
//               entwicklungRueckfrage(n,projektId,{meilensteinId,text,anId?}) · entwicklungDokumentSpeichern(n,{…,daten})
//               entwicklungDokumentLesen(n,id) · entwicklungEinladungInfo(token) · entwicklungEinladungAnnehmen(n,token)
//               entwicklungZaehler(n)
//
// Nur serverseitig verwenden.

import * as demo from "./demo/entwicklung";
import * as frappe from "./frappe/entwicklung";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

export const ENTWICKLUNG_OPERATIONEN = [
  "entwicklungPortfolio", "entwicklungProjekt", "entwicklungAuswahl", "entwicklungAnlegen", "entwicklungAendern", "entwicklungEintragSpeichern",
  "entwicklungEintragLoeschen", "entwicklungAktion", "entwicklungAssistent", "entwicklungGutachterEinladen", "entwicklungFristen", "entwicklungMeine",
  "entwicklungExtern", "entwicklungMeilensteinMelden", "entwicklungRueckfrage", "entwicklungDokumentSpeichern", "entwicklungDokumentLesen",
  "entwicklungEinladungInfo", "entwicklungEinladungAnnehmen", "entwicklungZaehler",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = ENTWICKLUNG_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Entwicklung ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export function entwicklungBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}
// src/lib/plattform/backend/frappe/entwicklung.js
//
// Frappe-Adapter „Projektentwicklung“. Methoden in oekoinvest_app.plattform.api.entwicklung – Vertrag: docs/API.md,
// Abschnitt 11. Signaturen identisch zu backend/demo/entwicklung.js. Frappe prüft Rolle UND Eigentum selbst.

import { METHODEN, frappeAufruf as aufruf } from "../frappe";

Object.assign(METHODEN, {
  entwicklungPortfolio: "entwicklung.portfolio",
  entwicklungProjekt: "entwicklung.holen",
  entwicklungAuswahl: "entwicklung.auswahl",
  entwicklungAnlegen: "entwicklung.anlegen",
  entwicklungAendern: "entwicklung.aendern",
  entwicklungEintragSpeichern: "entwicklung.eintrag_speichern",
  entwicklungEintragLoeschen: "entwicklung.eintrag_loeschen",
  entwicklungAktion: "entwicklung.aktion",
  entwicklungAssistent: "entwicklung.assistent",
  entwicklungGutachterEinladen: "entwicklung.gutachter_einladen",
  entwicklungFristen: "entwicklung.fristen",
  entwicklungMeine: "entwicklung.meine",
  entwicklungExtern: "entwicklung.extern",
  entwicklungMeilensteinMelden: "entwicklung.meilenstein_melden",
  entwicklungRueckfrage: "entwicklung.rueckfrage",
  entwicklungDokumentSpeichern: "entwicklung.dokument_speichern",
  entwicklungDokumentLesen: "entwicklung.dokument_lesen",
  entwicklungEinladungInfo: "entwicklung.einladung_info",
  entwicklungEinladungAnnehmen: "entwicklung.einladung_annehmen",
  entwicklungZaehler: "entwicklung.zaehler",
});

export const entwicklungPortfolio = (n, filter = {}) => aufruf("entwicklungPortfolio", filter, n);
export const entwicklungProjekt = (n, id) => aufruf("entwicklungProjekt", { id }, n);
export const entwicklungAuswahl = (n) => aufruf("entwicklungAuswahl", {}, n);
export const entwicklungAnlegen = (n, daten = {}) => aufruf("entwicklungAnlegen", { daten }, n);
export const entwicklungAendern = (n, id, daten = {}) => aufruf("entwicklungAendern", { id, daten }, n);
export const entwicklungEintragSpeichern = (n, projektId, { art, id = null, daten = {} } = {}) => aufruf("entwicklungEintragSpeichern", { projektId, art, id, daten }, n);
export const entwicklungEintragLoeschen = (n, projektId, { art, id } = {}) => aufruf("entwicklungEintragLoeschen", { projektId, art, id }, n);
export const entwicklungAktion = (n, projektId, daten = {}) => aufruf("entwicklungAktion", { projektId, ...daten }, n);
export const entwicklungAssistent = (n, filter = {}) => aufruf("entwicklungAssistent", filter, n);
export const entwicklungGutachterEinladen = (n, projektId, daten = {}) => aufruf("entwicklungGutachterEinladen", { projektId, ...daten }, n);
export const entwicklungFristen = (n) => aufruf("entwicklungFristen", {}, n);
export const entwicklungMeine = (n) => aufruf("entwicklungMeine", {}, n);
export const entwicklungExtern = (n, id) => aufruf("entwicklungExtern", { id }, n);
export const entwicklungMeilensteinMelden = (n, projektId, meilensteinId, daten = {}) => aufruf("entwicklungMeilensteinMelden", { projektId, meilensteinId, ...daten }, n);
export const entwicklungRueckfrage = (n, projektId, daten = {}) => aufruf("entwicklungRueckfrage", { projektId, ...daten }, n);
/** Upload: Datei als Base64 (≤ 10 MB, Typ bereits an den ersten Bytes geprüft) – Frappe legt sie als private File ab */
export const entwicklungDokumentSpeichern = (n, { daten, ...rest } = {}) => aufruf("entwicklungDokumentSpeichern", { ...rest, inhalt: Buffer.from(daten).toString("base64") }, n);
export async function entwicklungDokumentLesen(n, id) {
  const r = await aufruf("entwicklungDokumentLesen", { id }, n);
  return { name: r.name, mime: r.mime, daten: Buffer.from(r.inhalt || "", "base64") };
}
export const entwicklungEinladungInfo = (token) => aufruf("entwicklungEinladungInfo", { token });
export const entwicklungEinladungAnnehmen = (n, token) => aufruf("entwicklungEinladungAnnehmen", { token }, n);
export const entwicklungZaehler = (n) => aufruf("entwicklungZaehler", {}, n);
// src/lib/plattform/server/route.js
//
// Gemeinsamer Rahmen aller Plattform-APIs:
//  - CSRF-Schutz: Mutationen nur mit passendem Origin-Header UND Content-Type JSON
//    (Uploads: multipart + Kopfzeile X-Plattform-Upload). Ein fremdes Formular kann weder
//    JSON senden noch eigene Kopfzeilen setzen; fremde fetch-Aufrufe scheitern am Origin.
//  - Sitzung aus dem signierten Cookie, Nutzer frisch aus dem Backend (Rollen, Sperre, Version)
//  - Rollenprüfung vorab (Eigentum prüft das Backend)
//  - Rate-Limits, Größenbegrenzung des Bodys
//  - Fehler → { ok:false, error, code } mit passendem HTTP-Status, Interna nur ins Log

import { NextResponse } from "next/server";
import { backend } from "../backend";
import { PlattformFehler } from "../fehler";
import { cookieName, cookieOptionen, tokenErstellen, tokenPruefen } from "../sitzung";
import { ipAdresse } from "@/lib/ipAdresse";
import { SITE } from "@/data/site";
import { grenze, rateLimit } from "./rateLimit";
import { adminRechtPruefen } from "./rechte"; // Backoffice-Unterrollen (Rechte-Matrix)

const KEIN_CACHE = { "Cache-Control": "no-store" };

export function antwort(daten, status = 200) {
  return NextResponse.json(daten, { status, headers: KEIN_CACHE });
}

export function fehlerAntwort(e) {
  if (e instanceof PlattformFehler) {
    return antwort({ ok: false, error: e.message, code: e.code }, e.status);
  }
  console.error("[plattform] Unerwarteter Fehler:", e);
  return antwort({ ok: false, error: "Es ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.", code: "fehler" }, 500);
}

function hostVon(url) {
  try {
    return new URL(url).host.toLowerCase();
  } catch {
    return "";
  }
}

/** Erlaubte Hosts für den Origin-Abgleich */
function erlaubteHosts(request) {
  const hosts = new Set();
  const h = request.headers.get("x-forwarded-host") || request.headers.get("host");
  if (h) hosts.add(h.split(",")[0].trim().toLowerCase());
  hosts.add(hostVon(SITE.url));
  for (const o of String(process.env.PLATTFORM_ORIGINS || "").split(",")) if (o.trim()) hosts.add(hostVon(o.trim()));
  return hosts;
}

/** CSRF: Origin muss zur eigenen Seite gehören */
export function herkunftPruefen(request) {
  const origin = request.headers.get("origin");
  if (!origin || origin === "null" || !erlaubteHosts(request).has(hostVon(origin))) {
    throw new PlattformFehler(403, "Anfrage von fremder Herkunft abgelehnt.", "herkunft");
  }
}

/** JSON-Body lesen (max. Bytes), muss ein Objekt sein */
export async function jsonLesen(request, maxBytes = 64 * 1024) {
  const typ = request.headers.get("content-type") || "";
  if (!typ.toLowerCase().startsWith("application/json")) throw new PlattformFehler(415, "Erwartet wird JSON.");
  const laenge = Number(request.headers.get("content-length") || 0);
  if (laenge > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
  const text = await request.text();
  if (text.length > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
  let daten;
  try {
    daten = text ? JSON.parse(text) : {};
  } catch {
    throw new PlattformFehler(400, "Ungültiges JSON.");
  }
  if (!daten || typeof daten !== "object" || Array.isArray(daten)) throw new PlattformFehler(400, "Ungültige Daten.");
  return daten;
}

/** Angemeldeten Nutzer aus dem Cookie lesen (oder null) */
export async function nutzerAusAnfrage(request, b = backend()) {
  const token = request.cookies.get(cookieName())?.value;
  if (!token) return null;
  const s = await tokenPruefen(token);
  if (!s) return null;
  // sitzungId: Sitzungseintrag muss bestehen (einzeln widerrufbar, siehe backend/demo/sicherheit.js)
  const u = await b.nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId });
  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
  return u;
}

/** Sitzungscookie setzen (sitzungId aus sitzungAnlegen – Anmeldung läuft über server/anmeldung.js) */
export async function sitzungSetzen(res, nutzer, { sitzungId = null } = {}) {
  const token = await tokenErstellen({ nutzerId: nutzer.id, version: nutzer.sitzungVersion || 0, sitzungId: sitzungId || nutzer.sitzung?.id || null });
  res.cookies.set(cookieName(), token, cookieOptionen());
  return res;
}

export function sitzungLoeschen(res) {
  res.cookies.set(cookieName(), "", { ...cookieOptionen(0), maxAge: 0 });
  return res;
}

/** Basis-URL für Links in E-Mails: in Produktion fest (kein Host-Header-Vertrauen) */
export function basisUrl(request) {
  if (process.env.NODE_ENV === "production") return (process.env.PLATTFORM_BASIS_URL || SITE.url).replace(/\/$/, "");
  return request.nextUrl.origin;
}

/** Nutzer für die Antwort an den Browser (ohne interne Felder) */
export function nutzerFuerBrowser(u) {
  if (!u) return null;
  return { id: u.id, email: u.email, vorname: u.vorname, nachname: u.nachname, firma: u.firma, telefon: u.telefon, rollen: u.rollen, emailBestaetigt: !!u.emailBestaetigt, suchprofil: u.suchprofil || null, mailEinstellungen: u.mailEinstellungen || null, backofficeRollen: u.backofficeRollen || null,
    // Login, Sicherheit & Teams: Komfort (Avatarfarbe, Sprache), Organisationskontext, 2FA-Status
    komfort: u.komfort || null, organisation: u.organisation || null, organisationen: u.organisationen || [], zweiFaktorAktiv: !!u.zweiFaktorAktiv, zweiFaktorPflichtOffen: !!u.zweiFaktorPflichtOffen };
}

/**
 * Route-Handler mit Rahmen.
 *
 * optionen:
 *   auth      true (Pflicht, Standard) | "optional" | false
 *   rollen    [..] – mindestens eine davon (admin darf immer)
 *   admin     true – nur Rolle admin
 *   limit     Name aus GRENZEN (je IP)
 *   json      true – JSON-Body lesen (Standard bei POST/PATCH/PUT/DELETE)
 *   upload    true – multipart statt JSON (eigene Kopfzeile Pflicht)
 *   maxBytes  Größe des JSON-Bodys
 *   ohne2fa   true – auch erreichbar, solange eine Pflicht-2FA noch nicht eingerichtet ist (Sicherheits-APIs)
 */
export function route(optionen, handler) {
  const o = { auth: true, ...optionen };
  return async (request, ctx) => {
    try {
      const mutation = !["GET", "HEAD", "OPTIONS"].includes(request.method);
      const params = ctx?.params ? await ctx.params : {};
      const ip = ipAdresse(request);

      if (mutation) {
        herkunftPruefen(request);
        if (o.upload && request.headers.get("x-plattform-upload") !== "1") throw new PlattformFehler(403, "Upload nur über das Portal.", "herkunft");
      }
      if (o.limit) rateLimit(`${o.limit}:${ip || "ohne-ip"}`, ...grenze(o.limit));

      const b = backend();
      let nutzer = null;
      if (o.auth) {
        nutzer = await nutzerAusAnfrage(request, b);
        if (!nutzer && o.auth === true) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
        if (nutzer) {
          const admin = nutzer.rollen?.includes("admin");
          if (o.admin && !admin) throw new PlattformFehler(403, "Nur für das Backoffice.");
          if (o.rollen && !admin && !o.rollen.some((r) => nutzer.rollen?.includes(r))) {
            throw new PlattformFehler(403, "Dafür fehlt Ihnen die passende Rolle.");
          }
          // Pflicht-2FA (Rolle, z. B. Backoffice): bis zur Einrichtung nur Sicherheits-APIs
          if (nutzer.zweiFaktorPflichtOffen && !o.ohne2fa && o.auth === true) {
            throw new PlattformFehler(403, "Für Ihr Konto ist die Zwei-Faktor-Anmeldung Pflicht. Bitte richten Sie sie unter „Sicherheit“ ein.", "zwei_faktor_pflicht");
          }
        }
      }

      const body = mutation && !o.upload && o.json !== false ? await jsonLesen(request, o.maxBytes) : undefined;
      if (nutzer) adminRechtPruefen(nutzer, { request, body, params, recht: o.recht }); // feine Backoffice-Rechte für /api/admin/**
      const ergebnis = await handler({ request, params, nutzer, body, backend: b, ip, suche: request.nextUrl.searchParams });
      if (ergebnis instanceof Response) return ergebnis;
      return antwort(ergebnis === undefined ? { ok: true } : ergebnis);
    } catch (e) {
      return fehlerAntwort(e);
    }
  };
}
// src/lib/plattform/server/rechte.js
//
// Durchsetzung der Backoffice-Unterrollen (src/lib/plattform/rechte.js):
//  - APIs: route() ruft adminRechtPruefen() für jede Anfrage auf /api/admin/** (nach dem Lesen des Bodys,
//    damit z. B. /api/admin/status die Objektart kennt). Option `recht` im route()-Aufruf überschreibt die
//    Ableitung aus dem Pfad.
//  - Seiten: server/seite.js prüft /portal/admin/** über seitenRechtOk().
// Nicht-Admins werden hier nicht geprüft (dafür sorgt `admin: true` in route() bzw. portalNutzer).

import { PlattformFehler } from "../fehler";
import { BEREICHE, STUFE_LABEL, apiAnforderungen, fehlendeRechte, darfLesen, seitenBereich } from "../rechte";

export function adminRechtPruefen(nutzer, { request, body, params, recht } = {}) {
  const pfad = request?.nextUrl?.pathname || "";
  if (!pfad.startsWith("/api/admin/") && !recht) return;
  if (!nutzer?.rollen?.includes("admin")) return;
  const fehlt = fehlendeRechte(nutzer, apiAnforderungen({ pfad, methode: request.method, body, params, recht }));
  if (fehlt.length) {
    const f = fehlt[0];
    throw new PlattformFehler(403, `Ihre Backoffice-Rolle erlaubt im Bereich „${BEREICHE[f.bereich] || f.bereich}“ kein ${STUFE_LABEL[f.stufe]}.`, "recht");
  }
}

/** Darf der Nutzer die Admin-Seite (Pfad) sehen? */
export function seitenRechtOk(nutzer, pfad) {
  const bereich = seitenBereich(pfad);
  return !bereich || darfLesen(nutzer, bereich);
}
// src/lib/plattform/server/seite.js
//
// Sitzung in Server-Komponenten (Seiten, Layouts). Die Middleware prüft vorab nur die
// Signatur; hier wird der Nutzer frisch geladen (Rollen, Sperre, Sitzungsversion).

import { cookies, headers } from "next/headers";
import { redirect, notFound } from "next/navigation";
import { backend } from "../backend";
import { cookieName, tokenPruefen } from "../sitzung";
import { PlattformFehler } from "../fehler";
import { seitenRechtOk } from "./rechte"; // Backoffice-Unterrollen

export async function aktuellerNutzer() {
  const token = (await cookies()).get(cookieName())?.value;
  if (!token) return null;
  const s = await tokenPruefen(token);
  if (!s) return null;
  const u = await backend().nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId }); // Sitzungseintrag muss bestehen
  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
  return u;
}

/** Aktuellen Pfad (von der Middleware als Kopfzeile gesetzt) für ?weiter= */
async function aktuellerPfad() {
  const h = await headers();
  const p = h.get("x-oi-pfad") || "/portal";
  return p.startsWith("/portal") ? p : "/portal";
}

/**
 * Für Portalseiten: Nutzer oder Weiterleitung zum Login.
 * rollen: mindestens eine davon (admin darf immer), sonst 404 (keine Existenz verraten).
 */
export async function portalNutzer({ rollen, admin } = {}) {
  const u = await aktuellerNutzer();
  if (!u) redirect(`/login?weiter=${encodeURIComponent(await aktuellerPfad())}`);
  // Pflicht-2FA noch nicht eingerichtet → nur die Sicherheitsseite
  if (u.zweiFaktorPflichtOffen && !(await aktuellerPfad()).startsWith("/portal/sicherheit")) redirect("/portal/sicherheit?pflicht=1");
  const istAdmin = u.rollen.includes("admin");
  if (admin && !istAdmin) notFound();
  if (admin && istAdmin && !seitenRechtOk(u, await aktuellerPfad())) notFound(); // Bereich ohne Leserecht der Unterrolle
  if (rollen && !istAdmin && !rollen.some((r) => u.rollen.includes(r))) notFound();
  return u;
}

export const istAdmin = (u) => !!u?.rollen?.includes("admin");
export const hatRolle = (u, ...rollen) => istAdmin(u) || rollen.some((r) => u?.rollen?.includes(r));

/** Backend-Aufruf in Seiten: 403/404 → notFound(), sonst weiterwerfen */
export async function laden(fn) {
  try {
    return await fn();
  } catch (e) {
    if (e instanceof PlattformFehler && [403, 404].includes(e.status)) notFound();
    throw e;
  }
}

