@frappe.whitelist(methods=["POST"])
def fall_anlegen(daten=None, als_benutzer=None):
	"""`daten.eingaben` sind bereits vom Adapter bereinigt (cockpitBereinigen inkl. Vorbelegung aus dem Bezug)."""
	n = nutzer(als_benutzer)
	schreib_noetig(n)
