import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite, voll, ...rest] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 } });
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 180000 });
  console.log("login", r.status());
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
  for (let i = 0; i < rest.length; i += 2) {
    fehler.length = 0;
    const res = await p.goto(B + rest[i + 1], { waitUntil: "load", timeout: 180000 });
    await p.waitForTimeout(1500);
    const ueber = await p.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
    await p.screenshot({ path: fileURLToPath(new URL(`./shots/fz_${rest[i]}_${breite}.png`, import.meta.url)), fullPage: voll === "1" });
    console.log(res.status(), rest[i], ueber ? "UEBERLAUF" : "", fehler.join(" | "));
  }
} finally {
  await b.close();
}

